    function run(address newOwner, bool byOwner) public payable {
        address initialOwner = c.owner();
        require(initialOwner == address(this), "deployer must be initial owner");

        address alt = address(uint160(uint256(keccak256(abi.encodePacked(newOwner, initialOwner)))) | 1);
        address other;
        if (alt == initialOwner) {
            other = address(uint160(alt) + 1);
        } else {
            other = alt;
        }
        address caller = byOwner ? initialOwner : other;

        // To make the external call go through the desired caller we use low-level call
        // with the target function selector and encode the arguments. This is a top-level call.
        bytes memory data = abi.encodeWithSignature("transferOwnership(address)", newOwner);
        (bool ok, ) = address(c).call(data);

        // Revert flag is captured in `ok`.
        bool reverted = !ok;

        // General rule: exactly when the caller is the current owner the call succeeds and sets owner to newOwner;
        // otherwise it reverts and owner stays with initialOwner.
        assert(byOwner == !reverted && (!byOwner == (reverted && c.owner() == initialOwner)) && (byOwner == (c.owner() == newOwner)));
    }

    receive() external payable {}
}

